ee:message.ee:set-payload:
%dw 2.0
output application/xml skipNullOn="everywhere"

ns open http://www.openuri.org/
ns tec http://com/tecnocom

var req = payload.doValidarEquiposPremisaInstalar.PeticionValidarEquiposPremisaInstalar
var encabezado = req.EncabezadoMensaje
var direccion = req.DetalleMensaje.Direccion

---
{
  open#doValidarEquiposPremisaInstalar: {
    tec#PeticionValidarEquiposPremisaInstalar: {
      tec#EncabezadoMensaje: {
        tec#IdDisponibilidad: encabezado.IdDisponibilidad default "",
        tec#NumeroOrdenAprovisionador: encabezado.NumeroOrdenAprovisionador default "",
        tec#NumeroRevision: encabezado.NumeroRevision default "",
        tec#FechaPeticionOrden: encabezado.FechaPeticionOrden default "",
        tec#TecnologiaETB: encabezado.TecnologiaETB default ""
      },
      tec#DetalleMensaje: {
        tec#Direccion: {
          tec#CodigoUnicoDireccion: direccion.CodigoUnicoDireccion default "",
          tec#IdCuentaServicio: direccion.IdCuentaServicio default "",
          tec#Equipos: {
            tec#Equipo: (direccion.Equipos default []) map (equipo) -> {
              tec#IdServicio: equipo.IdServicio default "",
              tec#SerialEquipo: equipo.SerialEquipo default "",
              tec#MacEquipo: equipo.MacEquipo default "",
              tec#Puertos: {
                tec#Puerto: (equipo.Puertos default []) map (puerto) -> {
                  tec#NombrePuerto: puerto.NombrePuerto default "",
                  tec#ServiciosPuerto: {
                    tec#IdServicioPuerto: puerto.ServiciosPuerto.IdServicioPuerto default ""
                  }
                }
              },
              tec#EquipoInstalado: equipo.EquipoInstalado default ""
            }
          }
        }
      }
    }
  }
}

%dw 2.0
output application/json skipNullOn="everywhere"

ns open http://www.openuri.org/
ns tec http://com/tecnocom

var body =
  payload.body.open#doValidarEquiposPremisaInstalarResponse.tec#RespuestaPeticionValidarEquiposPremisaInstalar

var encabezado = body.tec#EncabezadoMensaje
var equipo = body.tec#DetalleMensaje.tec#Equipo
var resultado = body.tec#DetalleMensaje.tec#Resultado

---
{
  cod_res:
    if ((resultado.tec#Resultado default "") == "OK")
      "200"
    else
      resultado.tec#CodigoErrorResultado default "",

  res:
    if ((resultado.tec#Resultado default "") == "OK")
      "Consulta exitosa."
    else
      resultado.tec#DescripcionErrorResultado default "",

  doValidarEquiposPremisaInstalarResponse: {
    RespuestaPeticionValidarEquiposPremisaInstalar: {
      EncabezadoMensaje: {
        IdDisponibilidad: encabezado.tec#IdDisponibilidad default "",
        NumeroOrdenAprovisionador: encabezado.tec#NumeroOrdenAprovisionador default "",
        NumeroRevision: (encabezado.tec#NumeroRevision default 0) as Number,
        FechaPeticionOrden: encabezado.tec#FechaPeticionOrden default ""
      },

      DetalleMensaje: {
        Equipo: {
          MarcaEquipo: equipo.tec#MarcaEquipo default "",
          IdServicio: equipo.tec#IdServicio default "",
          IndicadorObsolescencia: equipo.tec#IndicadorObsolescencia default "",
          SerialEquipo: equipo.tec#SerialEquipo default "",
          MacEquipo: equipo.tec#MacEquipo default "",
          TipoEquipo: equipo.tec#TipoEquipo default "",
          ModeloEquipo: equipo.tec#ModeloEquipo default "",
          IndicadorCompatibilidad: equipo.tec#IndicadorCompatibilidad default "",
          RespuestaCompatibilidad: equipo.tec#RespuestaCompatibilidad default "",

          Atributos: equipo.tec#Atributos.*tec#Atributo map ((atributo) -> {
            Atributo: atributo.tec#Atributo default "",
            Valor: atributo.tec#Valor default ""
          })
        }
      }
    }
  }
}
